// Simplified XState-like implementation
class StateMachine {
  constructor(config) {
    this.config = config;
    this.state = config.initial;
    this.context = config.context || {};
    this.subscribers = [];
  }

  subscribe(callback) {
    this.subscribers.push(callback);
    callback(this.getSnapshot());
    return () => {
      this.subscribers = this.subscribers.filter(cb => cb !== callback);
    };
  }

  getSnapshot() {
    return {
      value: this.state,
      context: this.context,
      matches: (target) => this.state === target
    };
  }

  send(event) {
    const currentStateConfig = this.config.states[this.state];
    if (!currentStateConfig || !currentStateConfig.on) return;

    const transition = currentStateConfig.on[event.type];
    if (!transition) return;

    // Execute actions
    if (transition.actions) {
      transition.actions.forEach(action => {
        if (typeof action === 'function') {
          this.context = action(this.context, event);
        } else if (action === 'increment') {
          this.context.count = (this.context.count || 0) + 1;
        }
      });
    }

    // Update state
    if (transition.target) {
      this.state = transition.target;
    }

    // Execute entry actions
    const newStateConfig = this.config.states[this.state];
    if (newStateConfig && newStateConfig.entry) {
      newStateConfig.entry.forEach(action => {
        if (typeof action === 'function') {
          this.context = action(this.context, event);
        }
      });
    }

    // Notify subscribers
    this.subscribers.forEach(cb => cb(this.getSnapshot()));
  }
}

// === EXAMPLE: E-Commerce Checkout Flow ===

const checkoutMachine = new StateMachine({
  id: 'checkout',
  initial: 'cart',
  context: {
    items: [],
    total: 0,
    paymentMethod: null,
    error: null
  },
  states: {
    cart: {
      on: {
        CHECKOUT: { target: 'shipping' }
      }
    },
    shipping: {
      on: {
        SUBMIT_SHIPPING: { target: 'payment' },
        BACK: { target: 'cart' }
      }
    },
    payment: {
      on: {
        SELECT_PAYMENT: {
          target: 'payment',
          actions: [(ctx, event) => ({ ...ctx, paymentMethod: event.method })]
        },
        PAY: { target: 'processing' },
        BACK: { target: 'shipping' }
      }
    },
    processing: {
      entry: [(ctx) => ({ ...ctx, error: null })],
      on: {
        SUCCESS: { target: 'confirmed' },
        FAILURE: { target: 'payment', actions: [(ctx, event) => ({ ...ctx, error: event.error })] }
      }
    },
    confirmed: {
      type: 'final'
    }
  }
});

// === EXAMPLE: Traffic Light (Hierarchical States) ===

const trafficLightMachine = new StateMachine({
  id: 'trafficLight',
  initial: 'green',
  context: { timer: 0 },
  states: {
    green: {
      on: { TIMER: { target: 'yellow' } }
    },
    yellow: {
      on: { TIMER: { target: 'red' } }
    },
    red: {
      on: { TIMER: { target: 'green' } }
    }
  }
});

// === Demo ===
console.log('XState Statechart Examples');
console.log('');

console.log('1. E-Commerce Checkout:');
checkoutMachine.subscribe((state) => {
  console.log('  State:', state.value, '| Context:', JSON.stringify(state.context));
});

checkoutMachine.send({ type: 'CHECKOUT' });
checkoutMachine.send({ type: 'SUBMIT_SHIPPING' });
checkoutMachine.send({ type: 'SELECT_PAYMENT', method: 'credit_card' });
checkoutMachine.send({ type: 'PAY' });
checkoutMachine.send({ type: 'SUCCESS' });

console.log('');
console.log('2. Traffic Light:');
trafficLightMachine.subscribe((state) => {
  console.log('  State:', state.value);
});

trafficLightMachine.send({ type: 'TIMER' });
trafficLightMachine.send({ type: 'TIMER' });
trafficLightMachine.send({ type: 'TIMER' });

console.log('');
console.log('XState Patterns Demonstrated:');
console.log('  - Finite State Machines');
console.log('  - State Transitions (on: EVENT -> target)');
console.log('  - Context (extended state)');
console.log('  - Actions (entry, transition)');
console.log('  - Hierarchical states (nested)');
console.log('  - Final states');
